import{_ as a,o as l,c as i,a2 as s}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill.md"}'),e={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill.md"};function n(o,t,h,d,r,p){return l(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="第-17-章-打造-skill-将方法论蒸馏为可执行-skill" tabindex="-1">第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill <a class="header-anchor" href="#第-17-章-打造-skill-将方法论蒸馏为可执行-skill" aria-label="Permalink to &quot;第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill&quot;">​</a></h1><blockquote><p>本章目标：掌握&quot;方法论蒸馏&quot;的完整手艺——从成功实践中提炼可复用步骤、写清边界、测试并共享。<strong>Skill 是经验的容器：造 Skill 最大的收获不是技能本身，而是逼你把&quot;我好像会做&quot;变成&quot;我知道怎么做，而且能做对&quot;。</strong></p></blockquote><h2 id="_17-1-什么是-打造-skill" tabindex="-1">17.1 什么是&quot;打造 Skill&quot; <a class="header-anchor" href="#_17-1-什么是-打造-skill" aria-label="Permalink to &quot;17.1 什么是&quot;打造 Skill&quot;&quot;">​</a></h2><p>第 5 章我们学会了&quot;用&quot;Skill。这一章学&quot;造&quot;。</p><p>打造 Skill 的过程，本质上是一次<strong>方法论蒸馏</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的一次成功实践 → 提炼出可复用的步骤 → 写成 Skill → 下次一键调用</span></span></code></pre></div><h3 id="_17-1-1-蒸馏的比喻" tabindex="-1">17.1.1 蒸馏的比喻 <a class="header-anchor" href="#_17-1-1-蒸馏的比喻" aria-label="Permalink to &quot;17.1.1 蒸馏的比喻&quot;">​</a></h3><p>想想菜谱的诞生：一位厨师做了一道好吃的菜，他不能只留下&quot;挺好吃的&quot;，而是要把<strong>原料、步骤、火候、注意事项</strong>写成菜谱——别人照着做也能做出来。<strong>Skill 就是 AI 界的菜谱。</strong></p><h2 id="_17-2-什么时候值得造一个-skill" tabindex="-1">17.2 什么时候值得造一个 Skill <a class="header-anchor" href="#_17-2-什么时候值得造一个-skill" aria-label="Permalink to &quot;17.2 什么时候值得造一个 Skill&quot;">​</a></h2><h3 id="_17-2-1-四个信号" tabindex="-1">17.2.1 四个信号 <a class="header-anchor" href="#_17-2-1-四个信号" aria-label="Permalink to &quot;17.2.1 四个信号&quot;">​</a></h3><ul><li>同一件事，你已经让我做过 <strong>2～3 次以上</strong>；</li><li>步骤基本固定，只是输入在变；</li><li>你和同事都频繁需要这个能力；</li><li>你想把个人经验变成团队资产。</li></ul><h3 id="_17-2-2-判断口诀" tabindex="-1">17.2.2 判断口诀 <a class="header-anchor" href="#_17-2-2-判断口诀" aria-label="Permalink to &quot;17.2.2 判断口诀&quot;">​</a></h3><blockquote><p><strong>&quot;这件事 10 遍之后还会一样吗？&quot;</strong> 会 → 值得造 Skill；不会 → 先别造。</p></blockquote><table tabindex="0"><thead><tr><th>判断</th><th>结论</th></tr></thead><tbody><tr><td>会重复 + 步骤固定</td><td>✅ 造 Skill</td></tr><tr><td>会重复 + 步骤常变</td><td>⚠️ 造&quot;参数化&quot; Skill</td></tr><tr><td>一次性 / 探索中</td><td>❌ 先对话，稳定了再沉淀</td></tr></tbody></table><h2 id="_17-3-打造-skill-的五步法" tabindex="-1">17.3 打造 Skill 的五步法 <a class="header-anchor" href="#_17-3-打造-skill-的五步法" aria-label="Permalink to &quot;17.3 打造 Skill 的五步法&quot;">​</a></h2><h3 id="第-1-步-回顾成功案例" tabindex="-1">第 1 步：回顾成功案例 <a class="header-anchor" href="#第-1-步-回顾成功案例" aria-label="Permalink to &quot;第 1 步：回顾成功案例&quot;">​</a></h3><p>找出最近一次做得好的任务，把全过程记下来——<strong>从失败和成功里都能提炼</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务：合并 CSV</span></span>
<span class="line"><span>成功路径：读 README → 理解格式 → 写脚本 → 验证行数 → 输出</span></span>
<span class="line"><span>踩坑记录：CSV 编码是 GBK，需转 UTF-8</span></span></code></pre></div><h3 id="第-2-步-提炼可复用步骤" tabindex="-1">第 2 步：提炼可复用步骤 <a class="header-anchor" href="#第-2-步-提炼可复用步骤" aria-label="Permalink to &quot;第 2 步：提炼可复用步骤&quot;">​</a></h3><p>去掉&quot;这一次的特殊性&quot;，留下&quot;下一次也适用&quot;的骨架：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入：多个 CSV 文件</span></span>
<span class="line"><span>步骤：读格式说明 → 检查字段 → 合并 → 校验行数 → 输出</span></span>
<span class="line"><span>输出：合并后的文件 + 校验报告</span></span></code></pre></div><p><strong>关键：把&quot;这一次的具体文件&quot;换成&quot;占位符/参数&quot;。</strong></p><table tabindex="0"><thead><tr><th>❌ 不可复用</th><th>✅ 可复用</th></tr></thead><tbody><tr><td>&quot;读取 data/a.csv 和 b.csv&quot;</td><td>&quot;读取 {输入目录} 下的 CSV 文件&quot;</td></tr><tr><td>&quot;列名是 日期/金额&quot;</td><td>&quot;按 {首行} 识别字段&quot;</td></tr></tbody></table><h3 id="第-3-步-写清边界与约定" tabindex="-1">第 3 步：写清边界与约定 <a class="header-anchor" href="#第-3-步-写清边界与约定" aria-label="Permalink to &quot;第 3 步：写清边界与约定&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>适用：同构 CSV 合并</span></span>
<span class="line"><span>不适用：异构/超大文件</span></span>
<span class="line"><span>约定：保留表头、数值取两位、必须校验</span></span></code></pre></div><p><strong>边界写得越清，Skill 越可靠</strong>——超出边界的输入，Skill 会拒绝或提示，而不是硬做。</p><h3 id="第-4-步-命名并测试" tabindex="-1">第 4 步：命名并测试 <a class="header-anchor" href="#第-4-步-命名并测试" aria-label="Permalink to &quot;第 4 步：命名并测试&quot;">​</a></h3><ul><li>名字要能&quot;望文生义&quot;：<code>merge-csv</code>、<code>weekly-report</code>；</li><li>用真实数据测 2～3 次，确保稳定；</li><li>记录测试结果（什么输入、什么输出、有无问题）。</li></ul><h3 id="第-5-步-沉淀与共享" tabindex="-1">第 5 步：沉淀与共享 <a class="header-anchor" href="#第-5-步-沉淀与共享" aria-label="Permalink to &quot;第 5 步：沉淀与共享&quot;">​</a></h3><ul><li>存入团队可访问的位置；</li><li>写一句话说明&quot;什么时候用它&quot;；</li><li>让团队其他人试用，收集反馈迭代。</li></ul><h2 id="_17-4-好-skill-的检查清单" tabindex="-1">17.4 好 Skill 的检查清单 <a class="header-anchor" href="#_17-4-好-skill-的检查清单" aria-label="Permalink to &quot;17.4 好 Skill 的检查清单&quot;">​</a></h2><ul><li>✅ 名称直观，说明清楚&quot;何时用/何时不用&quot;；</li><li>✅ 步骤可执行，不依赖特定上下文；</li><li>✅ 输入输出有约定，验收标准明确；</li><li>✅ 处理边界写清，超出边界会拒绝或提示；</li><li>✅ 有测试记录，不是&quot;我猜能用&quot;。</li></ul><h3 id="_17-4-1-好-skill-的结构模板" tabindex="-1">17.4.1 好 Skill 的结构模板 <a class="header-anchor" href="#_17-4-1-好-skill-的结构模板" aria-label="Permalink to &quot;17.4.1 好 Skill 的结构模板&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># {技能名}</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 用途</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{一句话：什么时候用它}</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 触发条件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{用户说什么话时触发}</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 输入</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{需要哪些输入、格式要求}</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 执行步骤</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{按顺序的可执行动作，每步可检查}</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 输出</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{交付什么、验收标准}</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 边界</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{适用/不适用/安全约定}</span></span></code></pre></div><h2 id="_17-5-常见误区" tabindex="-1">17.5 常见误区 <a class="header-anchor" href="#_17-5-常见误区" aria-label="Permalink to &quot;17.5 常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确做法</th></tr></thead><tbody><tr><td>把一次性任务做成 Skill</td><td>先确认真的会重复</td></tr><tr><td>步骤太依赖具体文件</td><td>用占位符，输入参数化</td></tr><tr><td>只写&quot;做什么&quot;不写&quot;怎么验&quot;</td><td>每一步配验收</td></tr><tr><td>一次想做一个大而全的 Skill</td><td>小而精，先解决一个问题</td></tr><tr><td>造完就锁死不迭代</td><td>用真实任务持续打磨</td></tr></tbody></table><h3 id="_17-5-1-小而精-原则" tabindex="-1">17.5.1 &quot;小而精&quot;原则 <a class="header-anchor" href="#_17-5-1-小而精-原则" aria-label="Permalink to &quot;17.5.1 &quot;小而精&quot;原则&quot;">​</a></h3><p><strong>一个 Skill 只解决一个问题。</strong> 想把&quot;写周报 + 做数据分析 + 发邮件&quot;塞进一个 Skill，等于三个 Skill 互相打架。拆开，各自小而精，还能自由组合。</p><h2 id="_17-6-skill-的进阶-从个人到团队资产" tabindex="-1">17.6 Skill 的进阶：从个人到团队资产 <a class="header-anchor" href="#_17-6-skill-的进阶-从个人到团队资产" aria-label="Permalink to &quot;17.6 Skill 的进阶：从个人到团队资产&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>说明</th></tr></thead><tbody><tr><td>个人 Skill</td><td>你自己用（解决你的重复劳动）</td></tr><tr><td>项目 Skill</td><td>项目成员共享（统一做法）</td></tr><tr><td>团队 Skill</td><td>全团队复用（最佳实践标准化）</td></tr></tbody></table><p><strong>个人积累 → 项目沉淀 → 团队复用</strong>——这是 Skill 价值的放大链，也是组织知识管理的第一步。</p><h2 id="_17-7-练习" tabindex="-1">17.7 练习 <a class="header-anchor" href="#_17-7-练习" aria-label="Permalink to &quot;17.7 练习&quot;">​</a></h2><ol><li>回顾你最近一个成功任务，按五步法写出 Skill 初稿；</li><li>用一套新的真实输入测试它，记录哪里需要修正；</li><li>迭代到&quot;换输入也能稳定跑&quot;为止，然后分享给同事试用；</li><li>用 17.4 的检查清单给自己打分，补齐缺口。</li></ol><hr><blockquote><p>小结：<strong>Skill 是经验的容器。</strong> 造 Skill 最大的收获不是技能本身，而是逼你把&quot;我好像会做&quot;变成&quot;我知道怎么做，而且能做对&quot;。五步法（回顾→提炼→边界→测试→共享）+ 小而精原则，就是全部心法。下一章：多 Agent 系统设计。</p></blockquote>`,45)])])}const c=a(e,[["render",n]]);export{u as __pageData,c as default};
